#!/usr/bin/env node
'use strict';
/**
 * Bundle packages/server + packages/shared into a single self-contained
 * CommonJS file that the Electron main process can require() directly.
 *
 * better-sqlite3 is kept external (it's a native .node module and must
 * be loaded from disk by the runtime — it cannot be bundled).
 *
 * Output: packages/desktop/src/server.bundle.cjs
 */

const path = require('node:path');
const esbuild = require('esbuild');

const ROOT = path.join(__dirname, '..', '..', '..');
const ENTRY = path.join(ROOT, 'packages', 'server', 'src', 'index.js');
const OUT = path.join(__dirname, '..', 'src', 'server.bundle.cjs');

(async () => {
  console.log('[bundle-server] Bundling server + shared…');

  const result = await esbuild.build({
    entryPoints: [ENTRY],
    bundle: true,
    platform: 'node',
    target: 'node22',
    format: 'cjs',
    outfile: OUT,
    // Native modules and anything that must be loaded from disk
    external: [
      'better-sqlite3',
      'electron',
    ],
    // Resolve workspace packages to their actual source
    alias: {
      '@orca/shared': path.join(ROOT, 'packages', 'shared', 'src', 'index.js'),
    },
    // Suppress the "top-level await" banner — our isMain guard is already there
    banner: {
      js: '/* Orca server bundle — generated by scripts/bundle-server.js */',
    },
    define: {
      // Disable the isMain auto-start: the bridge calls createApp() explicitly
      'import.meta.url': '"file:///bundled"',
    },
    metafile: true,
    logLevel: 'info',
  });

  // Print a brief summary of what was bundled
  const inputs = Object.keys(result.metafile.inputs).length;
  console.log(`[bundle-server] ✓ Bundled ${inputs} modules → src/server.bundle.cjs`);
})().catch((err) => {
  console.error('[bundle-server] ✗', err.message);
  process.exit(1);
});
